class User extends DataClass implements Insertable<User> {
  /// UUID v4 generated on the client
  final String id;

  /// Creation timestamp in UTC
  final DateTime createdAt;

  /// Last updated timestamp in UTC (used for incremental delta sync)
  final DateTime updatedAt;

  /// Soft deletion timestamp. If not null, the item is deleted.
  final DateTime? deletedAt;

  /// Sync status: 'pending' (needs upload to NestJS) or 'synced' (in sync with cloud)
  final String syncStatus;
  final String shopId;
  final String name;

  /// Role: 'owner', 'manager', 'cashier'
  final String role;

  /// 4 or 6 digit PIN code for rapid POS cashier login/switching
  final String pinCode;
  final bool isActive;
  const User({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.syncStatus,
    required this.shopId,
    required this.name,
    required this.role,
    required this.pinCode,
    required this.isActive,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['sync_status'] = Variable<String>(syncStatus);
    map['shop_id'] = Variable<String>(shopId);
    map['name'] = Variable<String>(name);
    map['role'] = Variable<String>(role);
    map['pin_code'] = Variable<String>(pinCode);
    map['is_active'] = Variable<bool>(isActive);
    return map;
  }

  UsersCompanion toCompanion(bool nullToAbsent) {
    return UsersCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      syncStatus: Value(syncStatus),
      shopId: Value(shopId),
      name: Value(name),
      role: Value(role),
      pinCode: Value(pinCode),
      isActive: Value(isActive),
    );
  }

  factory User.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return User(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
      syncStatus: serializer.fromJson<String>(json['syncStatus']),
      shopId: serializer.fromJson<String>(json['shopId']),
      name: serializer.fromJson<String>(json['name']),
      role: serializer.fromJson<String>(json['role']),
      pinCode: serializer.fromJson<String>(json['pinCode']),
      isActive: serializer.fromJson<bool>(json['isActive']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'deletedAt': serializer.toJson<DateTime?>(deletedAt),
      'syncStatus': serializer.toJson<String>(syncStatus),
      'shopId': serializer.toJson<String>(shopId),
      'name': serializer.toJson<String>(name),
      'role': serializer.toJson<String>(role),
      'pinCode': serializer.toJson<String>(pinCode),
      'isActive': serializer.toJson<bool>(isActive),
    };
  }

  User copyWith({
    String? id,
    DateTime? createdAt,
    DateTime? updatedAt,
    Value<DateTime?> deletedAt = const Value.absent(),
    String? syncStatus,
    String? shopId,
    String? name,
    String? role,
    String? pinCode,
    bool? isActive,
  }) => User(
    id: id ?? this.id,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    deletedAt: deletedAt.present ? deletedAt.value : this.deletedAt,
    syncStatus: syncStatus ?? this.syncStatus,
    shopId: shopId ?? this.shopId,
    name: name ?? this.name,
    role: role ?? this.role,
    pinCode: pinCode ?? this.pinCode,
    isActive: isActive ?? this.isActive,
  );
  User copyWithCompanion(UsersCompanion data) {
    return User(
      id: data.id.present ? data.id.value : this.id,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      deletedAt: data.deletedAt.present ? data.deletedAt.value : this.deletedAt,
      syncStatus: data.syncStatus.present
          ? data.syncStatus.value
          : this.syncStatus,
      shopId: data.shopId.present ? data.shopId.value : this.shopId,
      name: data.name.present ? data.name.value : this.name,
      role: data.role.present ? data.role.value : this.role,
