class Product extends DataClass implements Insertable<Product> {
  /// UUID v4 generated on the client
  final String id;

  /// Creation timestamp in UTC
  final DateTime createdAt;

  /// Last updated timestamp in UTC (used for incremental delta sync)
  final DateTime updatedAt;

  /// Soft deletion timestamp. If not null, the item is deleted.
  final DateTime? deletedAt;

  /// Sync status: 'pending' (needs upload to NestJS) or 'synced' (in sync with cloud)
  final String syncStatus;
  final String shopId;
  final String? categoryId;
  final String name;

  /// Barcode or SKU for camera / hardware scanner
  final String? barcode;

  /// Purchase/Cost price for COGS and gross profit margin calculation
  final double costPrice;

  /// Retail / Selling price
  final double sellingPrice;

  /// Current stock level on hand
  final int stockQuantity;

  /// Whether to decrement inventory on sale
  final bool trackStock;
  final String? imageUrl;
  final bool isActive;
  const Product({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.syncStatus,
    required this.shopId,
    this.categoryId,
    required this.name,
    this.barcode,
    required this.costPrice,
    required this.sellingPrice,
    required this.stockQuantity,
    required this.trackStock,
    this.imageUrl,
    required this.isActive,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['sync_status'] = Variable<String>(syncStatus);
    map['shop_id'] = Variable<String>(shopId);
    if (!nullToAbsent || categoryId != null) {
      map['category_id'] = Variable<String>(categoryId);
    }
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || barcode != null) {
      map['barcode'] = Variable<String>(barcode);
    }
    map['cost_price'] = Variable<double>(costPrice);
    map['selling_price'] = Variable<double>(sellingPrice);
    map['stock_quantity'] = Variable<int>(stockQuantity);
